// ============================================================
// BACKGROUND: BMW IMAGE SPINNING CLOCKWISE
// ============================================================
const bgCanvas = document.getElementById("bgCanvas");
const bgCtx = bgCanvas.getContext("2d");

function resizeBg() {
  bgCanvas.width = window.innerWidth;
  bgCanvas.height = window.innerHeight;
}
resizeBg();
window.addEventListener("resize", resizeBg);

const carImg = new Image();
carImg.src =
  "data:image/jpeg;base64,";

let bgAngle = 0;

function drawBg(t) {
  const W = bgCanvas.width,
    H = bgCanvas.height;
  bgCtx.clearRect(0, 0, W, H);

  // Dark base
  bgCtx.fillStyle = "#020508";
  bgCtx.fillRect(0, 0, W, H);

  if (carImg.complete && carImg.naturalWidth > 0) {
    const cx = W * 0.5;
    const cy = H * 0.5;

    // Scale to fill screen (cover behaviour)
    const imgAspect = carImg.naturalWidth / carImg.naturalHeight;
    const screenAspect = W / H;
    let drawW, drawH;
    if (imgAspect > screenAspect) {
      drawH = H * 1.1;
      drawW = drawH * imgAspect;
    } else {
      drawW = W * 1.1;
      drawH = drawW / imgAspect;
    }

    // Clockwise spin: increase angle each frame
    bgAngle += 0.003; // radians per frame (~0.17 deg/frame)

    bgCtx.save();
    bgCtx.translate(cx, cy);
    bgCtx.rotate(bgAngle);

    // Subtle pulsing scale for drama
    const pulse = 1 + 0.015 * Math.sin(t * 0.0008);
    bgCtx.scale(pulse, pulse);

    bgCtx.drawImage(carImg, -drawW / 2, -drawH / 2, drawW, drawH);
    bgCtx.restore();

    // Deep vignette on top of image
    const vig = bgCtx.createRadialGradient(cx, cy, H * 0.1, cx, cy, H * 0.9);
    vig.addColorStop(0, "rgba(2,5,8,0)");
    vig.addColorStop(0.5, "rgba(2,5,8,0.25)");
    vig.addColorStop(1, "rgba(2,5,8,0.85)");
    bgCtx.fillStyle = vig;
    bgCtx.fillRect(0, 0, W, H);

    // Blue tint overlay
    bgCtx.fillStyle = "rgba(10,30,60,0.25)";
    bgCtx.fillRect(0, 0, W, H);
  }

  requestAnimationFrame(drawBg);
}
carImg.onload = () => requestAnimationFrame(drawBg);
// Start even if image loads fast
requestAnimationFrame(drawBg);

// ============================================================
// RAIN
// ============================================================
const rainCanvas = document.getElementById("rainCanvas");
const rainCtx = rainCanvas.getContext("2d");
function resizeRain() {
  rainCanvas.width = window.innerWidth;
  rainCanvas.height = window.innerHeight;
}
resizeRain();
window.addEventListener("resize", resizeRain);

const drops = Array.from({ length: 220 }, () => ({
  x: Math.random() * window.innerWidth,
  y: Math.random() * window.innerHeight,
  len: 12 + Math.random() * 22,
  speed: 8 + Math.random() * 14,
  opacity: 0.1 + Math.random() * 0.35,
  angle: 0.12 + Math.random() * 0.08,
}));

function drawRain() {
  const W = rainCanvas.width,
    H = rainCanvas.height;
  rainCtx.clearRect(0, 0, W, H);
  drops.forEach((d) => {
    rainCtx.strokeStyle = `rgba(180,220,255,${d.opacity})`;
    rainCtx.lineWidth = 0.7;
    rainCtx.beginPath();
    rainCtx.moveTo(d.x, d.y);
    rainCtx.lineTo(
      d.x + d.len * Math.sin(d.angle),
      d.y + d.len * Math.cos(d.angle),
    );
    rainCtx.stroke();
    d.y += d.speed;
    d.x += d.speed * Math.sin(d.angle);
    if (d.y > H + 30) {
      d.y = -20;
      d.x = Math.random() * W;
    }
  });
  requestAnimationFrame(drawRain);
}
drawRain();

// ============================================================
// SCROLL NAV
// ============================================================
window.addEventListener("scroll", () => {
  document
    .getElementById("navbar")
    .classList.toggle("solid", window.scrollY > 60);
});

// ============================================================
// SCROLL REVEAL
// ============================================================
const ro = new IntersectionObserver(
  (entries) => {
    entries.forEach((e) => {
      if (e.isIntersecting) e.target.classList.add("visible");
    });
  },
  { threshold: 0.1 },
);
document.querySelectorAll(".reveal").forEach((el) => ro.observe(el));

// ============================================================
// STAT COUNTERS
// ============================================================
const co = new IntersectionObserver(
  (entries) => {
    entries.forEach((e) => {
      if (!e.isIntersecting) return;
      const el = e.target;
      const target = parseInt(el.dataset.target);
      let cur = 0;
      const inc = Math.ceil(target / 60);
      const iv = setInterval(() => {
        cur = Math.min(cur + inc, target);
        el.textContent =
          cur.toLocaleString() + (el.dataset.target == "99" ? "%" : "+");
        if (cur >= target) clearInterval(iv);
      }, 22);
      co.unobserve(el);
    });
  },
  { threshold: 0.5 },
);
document
  .querySelectorAll(".stat-num[data-target]")
  .forEach((el) => co.observe(el));

// ============================================================
// TESTIMONIALS
// ============================================================
let tIdx = 0;
const testis = document.querySelectorAll(".testimonial");
const tDots = document.querySelectorAll(".t-dot");
function goT(i) {
  testis[tIdx].classList.remove("active");
  tDots[tIdx].classList.remove("active");
  tIdx = i;
  testis[tIdx].classList.add("active");
  tDots[tIdx].classList.add("active");
}
setInterval(() => goT((tIdx + 1) % testis.length), 5000);

// ============================================================
// UTILS
// ============================================================
function showToast(msg) {
  const t = document.getElementById("toast");
  t.textContent = msg;
  t.style.transform = "translateX(-50%) translateY(0)";
  setTimeout(() => {
    t.style.transform = "translateX(-50%) translateY(80px)";
  }, 2800);
}
function handleForm(e) {
  e.preventDefault();
  showToast("✓ Message sent! We'll contact you shortly.");
}
